// The PDF's QR codes: generated by tools/make-qr.mjs, committed as constants, never stale.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { ROOT } from './helpers.mjs';

const { qrModuleSource, QR_URLS } = await import(join(ROOT, 'tools/make-qr.mjs'));
const { QR_CODES } = await import(join(ROOT, 'app/js/core/qr-codes.js'));

test('app/js/core/qr-codes.js is up to date (run npm run make-qr)', () => {
  assert.equal(readFileSync(join(ROOT, 'app/js/core/qr-codes.js'), 'utf8'), qrModuleSource());
});

test('QR codes encode only fixed justid.candea.es URLs, as square module grids', () => {
  for (const [key, code] of Object.entries(QR_CODES)) {
    assert.equal(code.url, QR_URLS[key]);
    assert.match(code.url, /^https:\/\/justid\.candea\.es\//);
    assert.equal(code.rows.length, code.size);
    assert.ok(code.rows.every(r => r.length === code.size && /^[01]+$/.test(r)));
  }
});
